  'axt.Duration': r'''
{
  "type": "record",
  "name": "Duration",
  "namespace": "axt",
  "doc": "A length of time in three parts that are not converted into each other: calendar months, calendar days and elapsed milliseconds, as an INTERVAL of SQL. P1M2DT3H is 1 month, 2 days and 10800000 milliseconds; -PT15M is -900000 milliseconds. The parts that are not 0 all have the same sign. Added to a date and time, the months come first, then the days, then the milliseconds. Defined in spec/time.md. Its schema never changes.",
  "fields": [
    {
      "name": "months",
      "type": "int",
      "doc": "The number of calendar months, negative for a length back in time. A year is 12 months."
    },
    {
      "name": "days",
      "type": "int",
      "doc": "The number of calendar days, negative for a length back in time. A day on the wall clock, which may last 23 or 25 hours where the offset changes; a week is 7 days."
    },
    {
      "name": "millis",
      "type": "long",
      "doc": "The number of elapsed milliseconds, negative for a length back in time. Hours, minutes and seconds are carried here: an hour is 3600000 milliseconds, and 24 hours are not converted into a day."
    }
  ]
}
''',
